// Generate some finance history for the chart
const generateTransactions = (): Transaction[] => {
  const txs: Transaction[] = [];
  const today = new Date();

  // Generate rent for last 12 months for 5 properties
  for (let i = 0; i < 12; i++) {
    const date = new Date(today.getFullYear(), today.getMonth() - i, 1).toISOString();

    // Monthly Rent Income
    txs.push({
      id: `inc-p1-${i}`, propertyId: 'p1', amount: 12000, type: TransactionType.INCOME, category: 'Rent', date, description: 'Monthly Rent'
    });
    txs.push({
      id: `inc-p3-${i}`, propertyId: 'p3', amount: 18500, type: TransactionType.INCOME, category: 'Rent', date, description: 'Monthly Rent'
    });

    // Random Expenses
    if (i % 2 === 0) {
      txs.push({
        id: `exp-${i}`, propertyId: 'p1', amount: 500 + Math.random() * 1000, type: TransactionType.EXPENSE, category: 'Maintenance', date, description: 'Routine Maintenance'
      });
    }
  }
  return txs;
};

