import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { Property, Ticket, Transaction, TicketStatus } from './types';
import { SEED_PROPERTIES, SEED_TICKETS, SEED_TRANSACTIONS } from './constants';

interface AppContextType {
  properties: Property[];
  tickets: Ticket[];
  transactions: Transaction[];
  addProperty: (property: Property) => void;
  updateProperty: (property: Property) => void;
  deleteProperty: (id: string) => void;
  addTransaction: (transaction: Transaction) => void;
  updateTicketStatus: (id: string, status: TicketStatus) => void;
  addTicket: (ticket: Ticket) => void;
  isLoading: boolean;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider = ({ children }: { children: ReactNode }) => {
  const [properties, setProperties] = useState<Property[]>([]);
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Load data from LocalStorage or Seed on mount
  useEffect(() => {
    const storedProps = localStorage.getItem('pm_properties');
    const storedTickets = localStorage.getItem('pm_tickets');
    const storedTx = localStorage.getItem('pm_transactions');

    if (storedProps && storedTickets && storedTx) {
      setProperties(JSON.parse(storedProps));
      setTickets(JSON.parse(storedTickets));
      setTransactions(JSON.parse(storedTx));
    } else {
      // Seed Data
      setProperties(SEED_PROPERTIES);
      setTickets(SEED_TICKETS);
      setTransactions(SEED_TRANSACTIONS);

      localStorage.setItem('pm_properties', JSON.stringify(SEED_PROPERTIES));
      localStorage.setItem('pm_tickets', JSON.stringify(SEED_TICKETS));
      localStorage.setItem('pm_transactions', JSON.stringify(SEED_TRANSACTIONS));
    }
    setIsLoading(false);
  }, []);

  // Persistence helpers
  const saveProperties = (data: Property[]) => {
    setProperties(data);
    localStorage.setItem('pm_properties', JSON.stringify(data));
  };

  const saveTickets = (data: Ticket[]) => {
    setTickets(data);
    localStorage.setItem('pm_tickets', JSON.stringify(data));
  };

  const saveTransactions = (data: Transaction[]) => {
    setTransactions(data);
    localStorage.setItem('pm_transactions', JSON.stringify(data));
  };

  // Actions
  const addProperty = (property: Property) => {
    saveProperties([...properties, property]);
  };

  const updateProperty = (updated: Property) => {
    const newProps = properties.map(p => p.id === updated.id ? updated : p);
    saveProperties(newProps);
  };

  const deleteProperty = (id: string) => {
    saveProperties(properties.filter(p => p.id !== id));
    // Also cleanup related data? keeping simple for now.
  };

  const addTransaction = (transaction: Transaction) => {
    saveTransactions([transaction, ...transactions]);
  };

  const updateTicketStatus = (id: string, status: TicketStatus) => {
    const newTickets = tickets.map(t => t.id === id ? { ...t, status } : t);
    saveTickets(newTickets);
  };

  const addTicket = (ticket: Ticket) => {
    saveTickets([ticket, ...tickets]);
  };

  return (
    <AppContext.Provider value={{
      properties,
      tickets,
      transactions,
      addProperty,
      updateProperty,
      deleteProperty,
      addTransaction,
      updateTicketStatus,
      addTicket,
      isLoading
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within AppProvider');
  return context;
};

import React from 'react';
import { useApp } from '../AppContext';
import { TicketStatus, TransactionType } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Building2, Wallet, AlertCircle, Percent } from 'lucide-react';

export const Dashboard = () => {
  const { properties, tickets, transactions } = useApp();

  // 1. Calculate Stats
  const totalUnits = properties.reduce((sum, p) => sum + p.units, 0);

  const currentMonth = new Date().getMonth();
  const monthlyCashflow = transactions
    .filter(t => new Date(t.date).getMonth() === currentMonth)
    .reduce((sum, t) => t.type === TransactionType.INCOME ? sum + t.amount : sum - t.amount, 0);

  const openTickets = tickets.filter(t => t.status !== TicketStatus.DONE).length;

  // Dummy vacancy calculation (assuming 5% if no real data tracking tenants)
  const vacancyRate = 4.2; 

  // 2. Prepare Chart Data (Last 6 Months)
  const chartData = [];
  const today = new Date();
  for (let i = 5; i >= 0; i--) {
    const d = new Date(today.getFullYear(), today.getMonth() - i, 1);
    const monthName = d.toLocaleString('default', { month: 'short' });

    const income = transactions
      .filter(t => {
        const tDate = new Date(t.date);
        return tDate.getMonth() === d.getMonth() && tDate.getFullYear() === d.getFullYear() && t.type === TransactionType.INCOME;
      })
      .reduce((sum, t) => sum + t.amount, 0);

    chartData.push({ name: monthName, income });
  }

  // 3. Urgent Tasks Logic
  const urgentTickets = tickets.filter(t => t.priority === 'HIGH' && t.status !== TicketStatus.DONE);

  return (
    <div className="space-y-6 animate-fade-in">
      <h1 className="text-3xl font-bold text-slate-900 tracking-tight">Executive Dashboard</h1>

      {/* Top Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard 
          title="Total Units" 
          value={totalUnits} 
          icon={<Building2 className="text-blue-600" size={24} />} 
          trend="+2 this year"
        />
        <StatCard 
          title="Monthly Cashflow" 
          value={`$${monthlyCashflow.toLocaleString()}`} 
          icon={<Wallet className="text-green-600" size={24} />} 
          trend="Current Month"
          positive={monthlyCashflow > 0}
        />
        <StatCard 
          title="Vacancy Rate" 
          value={`${vacancyRate}%`} 
          icon={<Percent className="text-orange-600" size={24} />} 
          trend="Target: <5%"
        />
        <StatCard 
          title="Open Tickets" 
          value={openTickets} 
          icon={<AlertCircle className="text-red-600" size={24} />} 
          trend={`${urgentTickets.length} Urgent`}
          isAlert={openTickets > 5}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Chart */}
        <div className="lg:col-span-2 bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <h2 className="text-lg font-semibold text-slate-800 mb-4">Revenue Trends (6 Months)</h2>
          <div className="h-72">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b'}} tickFormatter={(value) => `$${value/1000}k`} />
                <Tooltip 
                  cursor={{fill: '#f1f5f9'}}
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="income" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={40} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Urgent Tasks */}
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <h2 className="text-lg font-semibold text-slate-800 mb-4">Attention Required</h2>
          <div className="space-y-4">
            {urgentTickets.length === 0 && (
              <p className="text-slate-500 text-sm">No urgent issues.</p>
            )}
            {urgentTickets.map(ticket => (
              <div key={ticket.id} className="flex items-start gap-3 p-3 bg-red-50 border border-red-100 rounded-lg">
                <div className="mt-1 w-2 h-2 rounded-full bg-red-500 shrink-0" />
                <div>
                  <h4 className="text-sm font-medium text-red-900">{ticket.title}</h4>
                  <p className="text-xs text-red-700 mt-1 line-clamp-2">{ticket.description}</p>
                </div>
              </div>
            ))}
            <div className="flex items-start gap-3 p-3 bg-slate-50 border border-slate-100 rounded-lg">
              <div className="mt-1 w-2 h-2 rounded-full bg-amber-500 shrink-0" />
              <div>
                <h4 className="text-sm font-medium text-slate-900">Missing Rent: Unit 4B</h4>
                <p className="text-xs text-slate-600 mt-1">Payment is 5 days overdue.</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ title, value, icon, trend, isAlert, positive }: any) => (
  <div className={`p-6 rounded-xl border shadow-sm transition-all hover:shadow-md ${isAlert ? 'bg-red-50 border-red-200' : 'bg-white border-slate-200'}`}>
    <div className="flex justify-between items-start mb-4">
      <div>
        <p className="text-sm font-medium text-slate-500">{title}</p>
        <h3 className="text-2xl font-bold text-slate-900 mt-1">{value}</h3>
      </div>
      <div className={`p-2 rounded-lg ${isAlert ? 'bg-red-100' : 'bg-slate-50'}`}>
        {icon}
      </div>
    </div>
    <div className="flex items-center text-xs">
      <span className={`font-medium ${isAlert ? 'text-red-600' : 'text-slate-600'}`}>
        {trend}
      </span>
    </div>
  </div>
);

import React, { useState } from 'react';
import { useApp } from '../AppContext';
import { Property } from '../types';
import { Plus, Building, MapPin, Trash2, Edit2, X } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';

export const Portfolio = () => {
  const { properties, addProperty, deleteProperty, updateProperty } = useApp();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<Property>>({});

  const handleOpenModal = (property?: Property) => {
    if (property) {
      setEditingId(property.id);
      setFormData(property);
    } else {
      setEditingId(null);
      setFormData({});
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.address || !formData.city || !formData.purchasePrice) {
      alert("Please fill in all required fields");
      return;
    }

    const payload: Property = {
      id: editingId || Date.now().toString(), // Simple ID gen
      address: formData.address!,
      city: formData.city!,
      zipCode: formData.zipCode || '',
      yearBuilt: Number(formData.yearBuilt) || 2000,
      purchasePrice: Number(formData.purchasePrice) || 0,
      units: Number(formData.units) || 1,
    };

    if (editingId) {
      updateProperty(payload);
    } else {
      addProperty(payload);
    }
    setIsModalOpen(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-bold text-slate-900 tracking-tight">Portfolio Management</h1>
        <button 
          onClick={() => handleOpenModal()}
          className="bg-slate-900 hover:bg-slate-800 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition-colors shadow-sm text-sm font-medium"
        >
          <Plus size={18} />
          Add Property
        </button>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              <th className="p-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Property</th>
              <th className="p-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Location</th>
              <th className="p-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Units</th>
              <th className="p-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Purchase Price</th>
              <th className="p-4 text-xs font-semibold text-slate-500 uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {properties.map(property => (
              <tr key={property.id} className="hover:bg-slate-50 transition-colors group">
                <td className="p-4">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded bg-slate-100 flex items-center justify-center text-slate-400">
                      <Building size={20} />
                    </div>
                    <div>
                      <p className="font-medium text-slate-900">{property.address}</p>
                      <p className="text-xs text-slate-500">Built {property.yearBuilt}</p>
                    </div>
                  </div>
                </td>
                <td className="p-4 text-sm text-slate-600">
                  <div className="flex items-center gap-1">
                    <MapPin size={14} className="text-slate-400" />
                    {property.city}, {property.zipCode}
