               </div>
            </div>
          ))}
          {colTickets.length === 0 && (
            <div className="text-center py-10 text-slate-400 text-sm border-2 border-dashed border-slate-200 rounded-lg">
                No tickets here
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="h-[calc(100vh-140px)] flex flex-col">
      <h1 className="text-3xl font-bold text-slate-900 tracking-tight mb-6 flex-none">Maintenance Center</h1>
