export enum TicketStatus {
  OPEN = 'OPEN',
  IN_PROGRESS = 'IN_PROGRESS',
  DONE = 'DONE',
}

export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE',
}

export interface PropertyFinancials {
  // Purchasing Costs %
  transferTaxPercent: number; // Grunderwerbsteuer (e.g. 3.5 - 6.5%)
  notaryPercent: number;      // Notar & Grundbuch (approx 1.5 - 2.0%)
  agentPercent: number;       // Makler (3.57 - 7.14%)

  // Running Costs (Monthly)
  coldRent: number;           // Kaltmiete
  operatingCostsRecoverable: number; // Umlagefähige Nebenkosten
  operatingCostsNonRecoverable: number; // Nicht-umlagefähige BWK (Verwaltung, IH-Rücklage)

  // Loan
  loanInterestRate: number;   // Zins %
  loanRepaymentRate: number;  // Tilgung % (initial)
  loanAmount: number;         // Darlehenshöhe

  // Tax
  landValuePercent: number;   // Bodenrichtwertanteil (Standard 20%, Buildings 80%)
  personalTaxRate: number;    // Persönlicher Steuersatz (e.g. 42%)
}

export interface Property {
  id: string;
  address: string;
  city: string;
  zipCode: string;
  yearBuilt: number;
  purchasePrice: number; // Kaufpreis (Netto)
  purchaseDate: string;  // Kaufdatum for 15% rule
  units: number;
  imageUrl?: string;
  financials: PropertyFinancials; // Expanded Data
}

export interface Ticket {
  id: string;
  propertyId: string;
  title: string;
  description: string;
  status: TicketStatus;
  priority: 'LOW' | 'MEDIUM' | 'HIGH';
  createdAt: string;
}

export interface Transaction {
  id: string;
  propertyId: string;
  amount: number;
  type: TransactionType;
  category: string; // "Renovation" category triggers 15% rule logic
  date: string;
  description: string;
}

export interface DashboardStats {
