// Helper to calculate Acquisition Costs
export const calculatePurchaseCosts = (price: number, financials: Property['financials']) => {
  const tax = price * (financials.transferTaxPercent / 100);
  const notary = price * (financials.notaryPercent / 100);
  const agent = price * (financials.agentPercent / 100);
  return {
    tax,
    notary,
    agent,
    total: price + tax + notary + agent
  };
};

// Helper for Monthly Cashflow Waterfall
export const calculateMonthlyCashflow = (prop: Property) => {
  const f = prop.financials;

  // 1. Income
  const warmRent = f.coldRent + f.operatingCostsRecoverable;

  // 2. Costs
  const totalOperatingCosts = f.operatingCostsRecoverable + f.operatingCostsNonRecoverable;

  // 3. Debt Service (Kapitaldienst)
  // Annual Payment = Loan * (Interest% + Repayment%)
  const annualDebtService = f.loanAmount * ((f.loanInterestRate + f.loanRepaymentRate) / 100);
  const monthlyDebtService = annualDebtService / 12;

  // 4. Pre-Tax Cashflow
  const preTaxCashflow = warmRent - totalOperatingCosts - monthlyDebtService;

  // 5. Tax Calculation
  // AfA (Depreciation) - Linear 2% of Building Value (usually 80% of price)
  const buildingValue = prop.purchasePrice * ((100 - f.landValuePercent) / 100);
  const annualAfA = buildingValue * 0.02;
  const monthlyAfA = annualAfA / 12;

  const monthlyInterest = (f.loanAmount * (f.loanInterestRate / 100)) / 12;

  // Taxable Income = Cold Rent - Interest - NonRecoverableCosts - AfA
  const taxableIncome = f.coldRent - monthlyInterest - f.operatingCostsNonRecoverable - monthlyAfA;

  const estimatedTax = taxableIncome > 0 ? taxableIncome * (f.personalTaxRate / 100) : 0;

  // 6. Post-Tax Cashflow
  const postTaxCashflow = preTaxCashflow - estimatedTax;

  // 7. Hidden Wealth (Tilgung/Amortization)
  const monthlyAmortization = monthlyDebtService - monthlyInterest;

  return {
    warmRent,
    totalOperatingCosts,
    monthlyDebtService,
    monthlyInterest,
    monthlyAmortization,
    preTaxCashflow,
    monthlyAfA,
    taxableIncome,
    estimatedTax,
    postTaxCashflow
  };
};

// 15% Rule Check
// Sum of "Renovation" expenses in first 3 years > 15% of Building Value
export const calculate15PercentRule = (prop: Property, transactions: Transaction[]) => {
  const buildingValue = prop.purchasePrice * ((100 - prop.financials.landValuePercent) / 100);
  const limit15Percent = buildingValue * 0.15;

  const purchaseDate = new Date(prop.purchaseDate);
  const threeYearsLater = new Date(purchaseDate);
  threeYearsLater.setFullYear(purchaseDate.getFullYear() + 3);

  // Filter transactions
  const renovationCosts = transactions
    .filter(t => {
      const tDate = new Date(t.date);
      return (
        t.propertyId === prop.id &&
        t.type === TransactionType.EXPENSE &&
        (t.category.toLowerCase().includes('renovation') || t.category.toLowerCase().includes('sanierung')) &&
        tDate >= purchaseDate &&
        tDate <= threeYearsLater
      );
    })
    .reduce((sum, t) => sum + t.amount, 0);

  return {
    buildingValue,
    limit: limit15Percent,
    currentUsage: renovationCosts,
    isBreached: renovationCosts > limit15Percent,
    isWarning: renovationCosts > (limit15Percent * 0.8) // Warn at 80%
  };
};

