                                    <WaterfallRow label="- Non-Recoverable Costs (BWK)" value={-(formData.financials?.operatingCostsNonRecoverable || 0)} />
                                    <div className="bg-slate-50 p-2 px-4 font-bold border-y border-slate-200 flex justify-between">
                                        <span>= Op. Cashflow (Pre-Tax/Pre-Tilgung)</span>
                                        <span>{(calcData.taxableIncome + calcData.monthlyAfA).toFixed(2)} €</span>
                                    </div>
                                    <WaterfallRow label="- Repayment (Tilgung / Wealth Accumulation)" value={-calcData.monthlyAmortization} isBold />
                                    <div className="bg-slate-100 p-2 px-4 font-bold border-y border-slate-200 flex justify-between">
                                        <span>= Pre-Tax Cashflow</span>
                                        <span className={calcData.preTaxCashflow >= 0 ? 'text-emerald-600' : 'text-red-600'}>{calcData.preTaxCashflow.toFixed(2)} €</span>
