                                    <WaterfallRow label="- Est. Tax (Steuer)" value={-calcData.estimatedTax} subtext={`(Taxable Base: ${calcData.taxableIncome.toFixed(0)}€)`} />
                                    <div className="bg-slate-900 text-white p-3 px-4 font-bold flex justify-between">
                                        <span>= Post-Tax Cashflow</span>
                                        <span className={calcData.postTaxCashflow >= 0 ? 'text-emerald-400' : 'text-red-400'}>{calcData.postTaxCashflow.toFixed(2)} €</span>
                                    </div>
                                </div>

                                {/* Wealth Accumulation Box */}
                                <div className="bg-gradient-to-br from-emerald-50 to-teal-50 p-6 rounded-xl border border-emerald-100">
                                    <h4 className="text-emerald-800 font-bold mb-2 flex items-center gap-2">
                                        <TrendingUp size={18}/> Wealth Accumulation
                                    </h4>
                                    <p className="text-sm text-emerald-700 mb-4">
                                        Your tenants are paying off your loan. This is your "hidden" monthly savings rate.
                                    </p>
                                    <div className="flex items-end gap-2">
                                        <span className="text-3xl font-bold text-emerald-900">+ {calcData.monthlyAmortization.toFixed(2)} €</span>
                                        <span className="text-emerald-600 mb-1">/ month</span>
                                    </div>
                                </div>
                            </div>
                        )}
                    </form>
                </div>
            </div>

            {/* Footer Actions */}
            <div className="p-6 border-t border-slate-100 bg-white flex justify-end gap-3 flex-none">
                 <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-5 py-2.5 text-slate-600 hover:bg-slate-50 rounded-xl font-medium text-sm"
                >
                  Cancel
                </button>
                <button 
                  onClick={(e) => {
                      // Trigger form submit
                      document.getElementById('propertyForm')?.dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
                      // Since dispatching directly to react form is tricky without refs, let's just call submit logic if valid
                      if (formData.address && formData.purchasePrice) handleSubmit(e as any);
                  }}
                  className="px-5 py-2.5 bg-slate-900 hover:bg-slate-800 text-white rounded-xl font-medium shadow-lg shadow-slate-900/20 text-sm"
                >
                  {editingId ? 'Save Changes' : 'Acquire Asset'}
