import React from 'react';
import { useApp } from '../AppContext';
import { TransactionType } from '../types';
import { calculate15PercentRule, calculateMonthlyCashflow } from '../utils';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Building2, TrendingUp, DollarSign, Wallet, ArrowUpRight, ArrowDownRight, AlertTriangle, PiggyBank } from 'lucide-react';

export const Dashboard = () => {
  const { properties, transactions } = useApp();

  // 1. Calculate Investment KPIs
  const totalAssetValue = properties.reduce((sum, p) => sum + p.purchasePrice, 0);
  const totalUnits = properties.reduce((sum, p) => sum + p.units, 0);

  // Calculate Global Wealth Accumulation (Tilgung)
  const totalMonthlyAmortization = properties.reduce((sum, p) => {
      return sum + calculateMonthlyCashflow(p).monthlyAmortization;
  }, 0);

  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();

  const monthlyIncome = transactions
    .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear && t.type === TransactionType.INCOME;
    })
    .reduce((sum, t) => sum + t.amount, 0);

  const monthlyExpenses = transactions
    .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear && t.type === TransactionType.EXPENSE;
    })
    .reduce((sum, t) => sum + t.amount, 0);

  const netMonthlyIncome = monthlyIncome - monthlyExpenses;

  // Mock Occupancy Data for Pie Chart
  const occupancyData = [
    { name: 'Occupied', value: totalUnits - 1 },
    { name: 'Vacant', value: 1 },
  ];
  const COLORS = ['#10b981', '#cbd5e1']; 

  // 2. Prepare Area Chart Data (Revenue Trends)
  const chartData = [];
  const today = new Date();
  for (let i = 5; i >= 0; i--) {
    const d = new Date(today.getFullYear(), today.getMonth() - i, 1);
    const monthName = d.toLocaleString('default', { month: 'short' });

    const income = transactions
      .filter(t => {
        const tDate = new Date(t.date);
        return tDate.getMonth() === d.getMonth() && tDate.getFullYear() === d.getFullYear() && t.type === TransactionType.INCOME;
      })
      .reduce((sum, t) => sum + t.amount, 0);

    const expense = transactions
      .filter(t => {
        const tDate = new Date(t.date);
        return tDate.getMonth() === d.getMonth() && tDate.getFullYear() === d.getFullYear() && t.type === TransactionType.EXPENSE;
      })
      .reduce((sum, t) => sum + t.amount, 0);

    chartData.push({ name: monthName, income, expense, profit: income - expense });
  }

  // 3. 15% Rule Check
  const warningProperties = properties.map(p => {
      const check = calculate15PercentRule(p, transactions);
      return { ...p, ruleCheck: check };
  }).filter(p => p.ruleCheck.isWarning);

  return (
    <div className="space-y-8 animate-fade-in pb-8">
      <div>
        <h1 className="text-3xl font-bold text-slate-900 tracking-tight">Investment Overview</h1>
        <p className="text-slate-500 mt-1">Real-time performance metrics of your real estate portfolio.</p>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <KPI_Card 
          title="Total Asset Value" 
          value={`€${(totalAssetValue / 1000000).toFixed(1)}M`} 
          icon={<Building2 className="text-white" size={24} />} 
          bg="bg-gradient-to-br from-slate-800 to-slate-900"
          text="text-white"
          subText="Across 5 properties"
        />
        <KPI_Card 
          title="Net Monthly Income" 
          value={`€${netMonthlyIncome.toLocaleString()}`} 
          icon={<Wallet className="text-emerald-600" size={24} />} 
          bg="bg-white border border-slate-100"
          text="text-slate-900"
          trend="+12.5%"
          trendUp={true}
        />
        <KPI_Card 
          title="Wealth Accumulation" 
          value={`+€${Math.round(totalMonthlyAmortization).toLocaleString()}`} 
          icon={<PiggyBank className="text-blue-600" size={24} />} 
          bg="bg-white border border-slate-100"
          text="text-slate-900"
          subText="Monthly Loan Repayment"
        />
        <KPI_Card 
          title="Occupancy Rate" 
          value={`${Math.round(((totalUnits - 1) / totalUnits) * 100)}%`} 
          icon={<TrendingUp className="text-purple-600" size={24} />} 
          bg="bg-white border border-slate-100"
          text="text-slate-900"
          trend="Stable"
          trendUp={true}
        />
      </div>

      {/* 15% Rule Alert Section */}
      {warningProperties.length > 0 && (
          <div className="bg-amber-50 border border-amber-200 rounded-2xl p-6 shadow-sm">
            <div className="flex items-center gap-2 mb-4">
                <AlertTriangle className="text-amber-600" size={24} />
                <h3 className="text-lg font-bold text-amber-900">Tax Alert: 15% Rule Limit Approaching</h3>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {warningProperties.map(p => (
                    <div key={p.id} className="bg-white p-4 rounded-xl border border-amber-100 shadow-sm">
                        <p className="font-bold text-slate-800 text-sm truncate">{p.address}</p>
                        <div className="mt-3">
                            <div className="flex justify-between text-xs mb-1">
                                <span className="text-slate-500">Renovation Spend</span>
                                <span className="font-bold text-slate-900">
                                    {Math.round((p.ruleCheck.currentUsage / p.ruleCheck.limit) * 100)}%
                                </span>
                            </div>
                            <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
                                <div 
                                    className={`h-full rounded-full ${p.ruleCheck.isBreached ? 'bg-red-500' : 'bg-amber-500'}`} 
                                    style={{width: `${Math.min(100, (p.ruleCheck.currentUsage / p.ruleCheck.limit) * 100)}%`}}
                                ></div>
                            </div>
                            <div className="flex justify-between text-[10px] text-slate-400 mt-1">
                                <span>€{p.ruleCheck.currentUsage.toLocaleString()}</span>
                                <span>Limit: €{p.ruleCheck.limit.toLocaleString()}</span>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
          </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Financial Chart */}
        <div className="lg:col-span-2 bg-white p-8 rounded-2xl border border-slate-100 shadow-lg shadow-slate-200/50">
          <div className="flex justify-between items-center mb-8">
            <div>
                <h2 className="text-xl font-bold text-slate-900">Financial Performance</h2>
                <p className="text-sm text-slate-500">Income vs Expenses (Last 6 Months)</p>
            </div>
            <div className="flex items-center gap-2">
                <span className="flex items-center gap-1 text-xs font-medium text-slate-500"><div className="w-2 h-2 rounded-full bg-emerald-500"></div> Income</span>
                <span className="flex items-center gap-1 text-xs font-medium text-slate-500"><div className="w-2 h-2 rounded-full bg-slate-300"></div> Expense</span>
            </div>
          </div>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorIncome" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} tickFormatter={(value) => `€${value/1000}k`} />
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                  formatter={(value: number) => [`€${value.toLocaleString()}`, '']}
                />
                <Area type="monotone" dataKey="income" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorIncome)" />
                <Area type="monotone" dataKey="expense" stroke="#cbd5e1" strokeWidth={2} fillOpacity={0} fill="#cbd5e1" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Portfolio Stats & Distribution */}
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-lg shadow-slate-200/50">
                <h2 className="text-lg font-bold text-slate-900 mb-2">Occupancy Status</h2>
                <div className="h-[200px] relative">
                    <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                            <Pie
                                data={occupancyData}
                                innerRadius={60}
                                outerRadius={80}
                                paddingAngle={5}
                                dataKey="value"
                            >
                                {occupancyData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                ))}
                            </Pie>
                            <Tooltip />
                        </PieChart>
                    </ResponsiveContainer>
                    {/* Center Text */}
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                        <div className="text-center">
                             <span className="block text-3xl font-bold text-slate-900">{totalUnits}</span>
                             <span className="text-xs text-slate-500 uppercase tracking-wide">Units</span>
                        </div>
                    </div>
                </div>
                <div className="flex justify-center gap-6 mt-2">
                    <div className="text-center">
                        <p className="text-sm font-semibold text-slate-900">{totalUnits - 1}</p>
                        <p className="text-xs text-slate-500">Occupied</p>
                    </div>
                    <div className="text-center">
                        <p className="text-sm font-semibold text-slate-900">1</p>
                        <p className="text-xs text-slate-500">Vacant</p>
                    </div>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

const KPI_Card = ({ title, value, icon, bg, text, trend, trendUp, subText }: any) => (
