  personalTaxRate: 42,
  loanInterestRate: 4.0,
  loanRepaymentRate: 2.0,
  operatingCostsRecoverable: 150,
  operatingCostsNonRecoverable: 50,
  coldRent: 1000,
  loanAmount: 0
};

export const Portfolio = () => {
  const { properties, addProperty, deleteProperty, updateProperty } = useApp();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'general' | 'financials' | 'analysis'>('general');

  // Form State
  const [formData, setFormData] = useState<Partial<Property>>({ financials: DEFAULT_FINANCIALS });

  // Update loan amount automatically when price changes if it wasn't manually set
  useEffect(() => {
    if (formData.purchasePrice && (!formData.financials?.loanAmount || formData.financials.loanAmount === 0)) {
        setFormData(prev => ({
            ...prev,
            financials: {
                ...prev.financials!,
                loanAmount: prev.purchasePrice! // Default 100% financing
            }
        }));
    }
  }, [formData.purchasePrice]);

  const handleOpenModal = (property?: Property) => {
    if (property) {
      setEditingId(property.id);
      setFormData(JSON.parse(JSON.stringify(property))); // Deep copy
    } else {
      setEditingId(null);
      setFormData({ 
        financials: DEFAULT_FINANCIALS,
        purchaseDate: new Date().toISOString().split('T')[0]
      });
    }
    setActiveTab('general');
    setIsModalOpen(true);
  };

  const handleFinancialChange = (key: keyof Property['financials'], value: number) => {
    setFormData(prev => ({
        ...prev,
        financials: {
            ...prev.financials!,
            [key]: value
        }
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Basic validation
    if (!formData.address || !formData.city || !formData.purchasePrice) {
        alert("Please fill in Address, City, and Purchase Price.");
        return;
    }

    const payload: Property = {
      id: editingId || Date.now().toString(),
      address: formData.address!,
      city: formData.city || '',
      zipCode: formData.zipCode || '',
      yearBuilt: Number(formData.yearBuilt) || 2000,
      purchasePrice: Number(formData.purchasePrice) || 0,
      purchaseDate: formData.purchaseDate || new Date().toISOString().split('T')[0],
      units: Number(formData.units) || 1,
      imageUrl: formData.imageUrl || 'https://images.unsplash.com/photo-1560518883-ce09059eeffa',
      financials: formData.financials as Property['financials']
    };

    if (editingId) updateProperty(payload);
    else addProperty(payload);

    setIsModalOpen(false);
  };

  // Live Analysis Calculations
  const calcData = formData.purchasePrice && formData.financials ? calculateMonthlyCashflow(formData as Property) : null;
  const purchaseCosts = formData.purchasePrice && formData.financials ? calculatePurchaseCosts(formData.purchasePrice, formData.financials) : null;

  return (
    <div className="space-y-8 pb-10">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
            <h1 className="text-3xl font-bold text-slate-900 tracking-tight">Real Estate Assets</h1>
            <p className="text-slate-500 mt-1">Manage your holdings and track detailed financial KPIs.</p>
        </div>
        <div className="flex items-center gap-3">
             <button 
                onClick={() => handleOpenModal()}
                className="bg-slate-900 hover:bg-slate-800 text-white px-5 py-2.5 rounded-lg flex items-center gap-2 transition-all shadow-lg shadow-slate-900/20 text-sm font-medium hover:scale-[1.02] active:scale-95"
            >
                <Plus size={18} />
                New Asset
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {properties.map(property => (
            <PropertyCard 
                key={property.id} 
                property={property} 
                onEdit={() => handleOpenModal(property)}
                onDelete={() => {
                    if(confirm('Are you sure you want to delete this property? This cannot be undone.')) deleteProperty(property.id);
                }}
            />
        ))}
         {/* Add New Placeholder Card */}
         <button 
            onClick={() => handleOpenModal()}
            className="group flex flex-col items-center justify-center min-h-[340px] rounded-2xl border-2 border-dashed border-slate-300 hover:border-emerald-500 hover:bg-emerald-50/30 transition-all cursor-pointer bg-slate-50/50"
         >
            <div className="w-16 h-16 rounded-full bg-white group-hover:bg-emerald-500 flex items-center justify-center mb-4 shadow-sm group-hover:shadow-lg transition-all duration-300">
                <Plus size={32} className="text-slate-400 group-hover:text-white" />
            </div>
            <span className="font-semibold text-slate-500 group-hover:text-emerald-700">Add New Asset</span>
         </button>
      </div>

      {/* Calculator Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in duration-200 ring-1 ring-slate-900/5">
            {/* Header */}
            <div className="flex justify-between items-center p-6 border-b border-slate-100 bg-white flex-none z-10">
              <div>
                  <h2 className="text-xl font-bold text-slate-900 flex items-center gap-2">
                    {editingId ? <Edit2 size={20} className="text-blue-600"/> : <Plus size={20} className="text-emerald-600"/>}
                    {editingId ? 'Edit Asset & Financials' : 'Acquisition Calculator'}
                  </h2>
                  <p className="text-sm text-slate-500 mt-1">German Real Estate Investment Core</p>
              </div>
              <button 
                onClick={() => setIsModalOpen(false)} 
                className="text-slate-400 hover:text-slate-700 bg-slate-50 hover:bg-slate-100 p-2 rounded-full transition-all"
                aria-label="Close modal"
              >
                <X size={20} />
              </button>
            </div>

            <div className="flex flex-1 min-h-0 bg-slate-50/50">
                {/* Sidebar Tabs */}
                <div className="w-64 bg-white border-r border-slate-200 p-4 space-y-2 overflow-y-auto hidden md:block">
                    <TabButton active={activeTab === 'general'} onClick={() => setActiveTab('general')} icon={<Building size={18}/>} label="General Data" />
                    <TabButton active={activeTab === 'financials'} onClick={() => setActiveTab('financials')} icon={<Banknote size={18}/>} label="Financials" />
                    <TabButton active={activeTab === 'analysis'} onClick={() => setActiveTab('analysis')} icon={<Calculator size={18}/>} label="Analysis / Waterfall" />
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-8 relative">
                    <form id="propertyForm" onSubmit={handleSubmit} className="space-y-6 max-w-3xl mx-auto">

                        {/* Mobile Tabs */}
                        <div className="md:hidden flex gap-2 mb-6 overflow-x-auto pb-2">
                             <TabButton mobile active={activeTab === 'general'} onClick={() => setActiveTab('general')} icon={<Building size={18}/>} label="General" />
                             <TabButton mobile active={activeTab === 'financials'} onClick={() => setActiveTab('financials')} icon={<Banknote size={18}/>} label="Financials" />
                             <TabButton mobile active={activeTab === 'analysis'} onClick={() => setActiveTab('analysis')} icon={<Calculator size={18}/>} label="Analysis" />
                        </div>

                        {activeTab === 'general' && (
                            <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="md:col-span-2">
                                        <InputGroup label="Image URL" value={formData.imageUrl} onChange={v => setFormData({...formData, imageUrl: v})} placeholder="https://..." />
                                    </div>
                                    <div className="md:col-span-2">
                                        <InputGroup label="Street Address" value={formData.address} onChange={v => setFormData({...formData, address: v})} required autoFocus placeholder="e.g. 101 Innovation Blvd" />
                                    </div>
                                    <InputGroup label="City" value={formData.city} onChange={v => setFormData({...formData, city: v})} required placeholder="City Name" />
                                    <InputGroup label="Zip Code" value={formData.zipCode} onChange={v => setFormData({...formData, zipCode: v})} placeholder="00000" />
                                    <InputGroup label="Year Built" type="number" value={formData.yearBuilt} onChange={v => setFormData({...formData, yearBuilt: Number(v)})} />
                                    <InputGroup label="Units" type="number" value={formData.units} onChange={v => setFormData({...formData, units: Number(v)})} />
                                    <InputGroup label="Purchase Date" type="date" value={formData.purchaseDate} onChange={v => setFormData({...formData, purchaseDate: v})} />
                                </div>
                            </div>
                        )}

                        {activeTab === 'financials' && (
                            <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
                                <SectionHeader title="Purchase Data" />
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                    <InputGroup label="Purchase Price (€)" type="number" value={formData.purchasePrice} onChange={v => setFormData({...formData, purchasePrice: Number(v)})} required />
                                    <InputGroup label="Loan Amount (€)" type="number" value={formData.financials?.loanAmount} onChange={v => handleFinancialChange('loanAmount', Number(v))} />
                                    <div className="bg-emerald-50 p-4 rounded-xl border border-emerald-100 flex flex-col justify-center">
                                        <p className="text-xs text-emerald-600 font-bold uppercase tracking-wider">Total Invest</p>
                                        <p className="text-xl font-bold text-emerald-900 mt-1">
                                            {purchaseCosts ? `€${purchaseCosts.total.toLocaleString()}` : '-'}
                                        </p>
                                    </div>
                                </div>

                                <SectionHeader title="Operating Numbers (Monthly)" />
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                    <InputGroup label="Cold Rent (€)" type="number" value={formData.financials?.coldRent} onChange={v => handleFinancialChange('coldRent', Number(v))} />
                                    <InputGroup label="Recoverable Costs (€)" type="number" value={formData.financials?.operatingCostsRecoverable} onChange={v => handleFinancialChange('operatingCostsRecoverable', Number(v))} />
                                    <InputGroup label="Non-Recoverable (€)" type="number" value={formData.financials?.operatingCostsNonRecoverable} onChange={v => handleFinancialChange('operatingCostsNonRecoverable', Number(v))} />
                                </div>

                                <SectionHeader title="Loan & Tax Parameters" />
                                <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                                    <InputGroup label="Interest Rate (%)" type="number" step="0.1" value={formData.financials?.loanInterestRate} onChange={v => handleFinancialChange('loanInterestRate', Number(v))} />
                                    <InputGroup label="Repayment Rate (%)" type="number" step="0.1" value={formData.financials?.loanRepaymentRate} onChange={v => handleFinancialChange('loanRepaymentRate', Number(v))} />
                                    <InputGroup label="Tax Rate (%)" type="number" value={formData.financials?.personalTaxRate} onChange={v => handleFinancialChange('personalTaxRate', Number(v))} />
                                    <InputGroup label="Land Value (%)" type="number" value={formData.financials?.landValuePercent} onChange={v => handleFinancialChange('landValuePercent', Number(v))} />
                                </div>
                            </div>
                        )}

                        {activeTab === 'analysis' && calcData && (
                            <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
                                {/* Cashflow Waterfall Visualization */}
                                <div className="bg-white rounded-xl border border-slate-200 overflow-hidden text-sm shadow-sm">
                                    <div className="p-4 bg-slate-900 text-white font-bold flex justify-between items-center">
                                        <span className="flex items-center gap-2"><TrendingUp size={16}/> Cashflow Waterfall (Monthly)</span>
                                        <span className={`px-3 py-1 rounded-full ${calcData.postTaxCashflow >= 0 ? 'bg-emerald-500 text-white' : 'bg-red-500 text-white'}`}>
                                            Net: {calcData.postTaxCashflow.toFixed(2)} €
                                        </span>
                                    </div>
                                    <WaterfallRow label="Cold Rent (Kaltmiete)" value={formData.financials?.coldRent || 0} isPositive />
                                    <WaterfallRow label="- Interest (Zinsen)" value={-calcData.monthlyInterest} />
                                    <WaterfallRow label="- Non-Recoverable Costs (BWK)" value={-(formData.financials?.operatingCostsNonRecoverable || 0)} />
                                    <div className="bg-slate-50 p-3 px-4 font-bold border-y border-slate-200 flex justify-between">
                                        <span>= Op. Cashflow (Pre-Tax/Pre-Tilgung)</span>
                                        <span>{(calcData.taxableIncome + calcData.monthlyAfA).toFixed(2)} €</span>
                                    </div>
                                    <WaterfallRow label="- Repayment (Tilgung / Wealth Accumulation)" value={-calcData.monthlyAmortization} isBold />
                                    <div className="bg-slate-100 p-3 px-4 font-bold border-y border-slate-200 flex justify-between">
                                        <span>= Pre-Tax Cashflow</span>
                                        <span className={calcData.preTaxCashflow >= 0 ? 'text-emerald-600' : 'text-red-600'}>{calcData.preTaxCashflow.toFixed(2)} €</span>
                                    </div>
                                    <WaterfallRow label="- Est. Tax (Steuer)" value={-calcData.estimatedTax} subtext={`(Taxable Base: ${calcData.taxableIncome.toFixed(0)}€)`} />
                                    <div className="bg-slate-900 text-white p-4 px-4 font-bold flex justify-between items-center">
                                        <span className="text-slate-300">= Post-Tax Cashflow</span>
                                        <span className={`text-lg ${calcData.postTaxCashflow >= 0 ? 'text-emerald-400' : 'text-red-400'}`}>{calcData.postTaxCashflow.toFixed(2)} €</span>
                                    </div>
                                </div>

                                {/* Wealth Accumulation Box */}
                                <div className="bg-gradient-to-br from-emerald-50 to-teal-50 p-6 rounded-xl border border-emerald-100 shadow-sm">
                                    <h4 className="text-emerald-800 font-bold mb-2 flex items-center gap-2">
                                        <TrendingUp size={18}/> Wealth Accumulation
                                    </h4>
                                    <p className="text-sm text-emerald-700 mb-4 leading-relaxed">
                                        Your tenants are paying off your loan. This is your "hidden" monthly savings rate (Tilgung), which directly increases your net worth over time.
                                    </p>
                                    <div className="flex items-end gap-2">
                                        <span className="text-3xl font-bold text-emerald-900">+ {calcData.monthlyAmortization.toFixed(2)} €</span>
                                        <span className="text-emerald-600 mb-1 font-medium">/ month</span>
                                    </div>
                                </div>
                            </div>
                        )}
                    </form>
                </div>
            </div>

            {/* Footer Actions */}
            <div className="p-6 border-t border-slate-200 bg-white flex justify-end gap-3 flex-none z-10">
                 <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-6 py-2.5 text-slate-700 hover:bg-slate-100 rounded-xl font-medium text-sm transition-colors border border-transparent hover:border-slate-200"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  form="propertyForm"
                  className="px-6 py-2.5 bg-slate-900 hover:bg-slate-800 text-white rounded-xl font-medium shadow-lg shadow-slate-900/20 text-sm flex items-center gap-2 transition-transform active:scale-95"
                >
                  <Save size={18} />
                  {editingId ? 'Save Changes' : 'Acquire Asset'}
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// --- Subcomponents ---

const TabButton = ({ active, onClick, icon, label, mobile }: any) => (
    <button 
        type="button"
        onClick={onClick}
        className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all duration-200 ${mobile ? 'whitespace-nowrap flex-1 justify-center' : 'w-full'} ${
            active 
                ? 'bg-slate-100 text-slate-900 shadow-sm ring-1 ring-slate-200' 
                : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50'
        }`}
    >
        {React.cloneElement(icon, { size: 18, className: active ? 'text-blue-600' : 'text-slate-400' })} 
        {label}
    </button>
);

const InputGroup = ({ label, type = "text", value, onChange, required, autoFocus, step, placeholder }: any) => (
    <div>
        <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">{label} {required && <span className="text-red-500">*</span>}</label>
        <input 
            type={type}
            step={step}
            autoFocus={autoFocus}
            placeholder={placeholder}
            className="w-full p-3 bg-white border border-slate-300 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all text-sm font-semibold text-slate-900 placeholder:text-slate-300 shadow-sm"
            value={value || ''}
            onChange={e => onChange(e.target.value)}
            required={required}
        />
    </div>
);

const SectionHeader = ({ title }: { title: string }) => (
    <div className="flex items-center gap-4 pb-2 border-b border-slate-200 pt-2">
        <h3 className="text-sm font-bold text-slate-900 uppercase tracking-wider">{title}</h3>
    </div>
);

const WaterfallRow = ({ label, value, isPositive, isBold, subtext }: any) => (
    <div className={`p-3 px-4 flex justify-between items-center border-b border-slate-50 ${isBold ? 'font-bold bg-slate-50' : ''}`}>
        <div>
            <span className="text-slate-600">{label}</span>
            {subtext && <span className="ml-2 text-xs text-slate-400">{subtext}</span>}
        </div>
        <span className={isPositive ? 'text-emerald-600' : value < 0 ? 'text-slate-600' : 'text-slate-900'}>
            {value > 0 ? '+' : ''}{value.toFixed(2)} €
        </span>
    </div>
);

