                    </div>
                </div>

                <div className="mt-auto pt-4 border-t border-slate-100 flex justify-between items-center text-xs text-slate-500 font-medium">
                    <span className="flex items-center gap-1.5"><Bed size={16} className="text-slate-400"/> {property.units} Units</span>
                    <span className="flex items-center gap-1.5"><Maximize size={16} className="text-slate-400"/> {property.yearBuilt}</span>
                </div>
            </div>
        </div>
    )
}

import React from 'react';
import { useApp } from '../AppContext';
import { TicketStatus, Ticket } from '../types';
import { AlertCircle, CheckCircle, Clock, MoreVertical, MapPin, Calendar } from 'lucide-react';

export const Tickets = () => {
  const { tickets, updateTicketStatus, properties } = useApp();

  const getAddress = (id: string) => properties.find(p => p.id === id)?.address || 'Unknown';

  const KanbanColumn = ({ status, title, icon }: { status: TicketStatus, title: string, icon: React.ReactNode }) => {
    const colTickets = tickets.filter(t => t.status === status);

    return (
      <div className="flex-1 min-w-[300px] bg-slate-50/80 rounded-2xl p-4 flex flex-col gap-4 h-full border border-slate-100">
        <div className="flex items-center justify-between text-slate-800 font-bold mb-2 px-1">
          <div className="flex items-center gap-2">
            <div className="p-1.5 bg-white rounded-lg shadow-sm border border-slate-100">
                {icon}
            </div>
            {title}
          </div>
          <span className="bg-white border border-slate-200 text-slate-600 px-2.5 py-0.5 rounded-full text-xs font-semibold shadow-sm">
            {colTickets.length}
          </span>
        </div>

        <div className="space-y-3 overflow-y-auto h-full pr-2 scrollbar-hide">
          {colTickets.map(ticket => (
            <div key={ticket.id} className="bg-white p-5 rounded-xl shadow-sm border border-slate-200 group hover:shadow-md transition-all duration-200 hover:-translate-y-0.5">
               <div className="flex justify-between items-start mb-3">
                 <span className={`text-[10px] font-bold px-2.5 py-1 rounded-md uppercase tracking-wider border ${
                    ticket.priority === 'HIGH' ? 'bg-red-50 text-red-700 border-red-100' :
                    ticket.priority === 'MEDIUM' ? 'bg-amber-50 text-amber-700 border-amber-100' :
                    'bg-blue-50 text-blue-700 border-blue-100'
                 }`}>
                   {ticket.priority}
                 </span>
                 <div className="relative">
                    <select 
                        className="text-[10px] font-semibold bg-slate-50 border border-slate-200 rounded-lg p-1.5 outline-none cursor-pointer hover:bg-slate-100 transition-colors text-slate-600"
                        value={ticket.status}
                        onChange={(e) => updateTicketStatus(ticket.id, e.target.value as TicketStatus)}
                    >
                        <option value={TicketStatus.OPEN}>Move to Open</option>
                        <option value={TicketStatus.IN_PROGRESS}>Move to In Progress</option>
                        <option value={TicketStatus.DONE}>Move to Done</option>
                    </select>
                 </div>
               </div>

               <h4 className="font-bold text-slate-900 mb-1.5 leading-snug">{ticket.title}</h4>
               <p className="text-sm text-slate-500 mb-4 line-clamp-3 leading-relaxed">{ticket.description}</p>

               <div className="pt-3 border-t border-slate-50 flex flex-col gap-1.5">
                  <div className="flex items-center gap-1.5 text-xs font-medium text-slate-600">
                    <MapPin size={12} className="text-slate-400"/>
                    {getAddress(ticket.propertyId)}
                  </div>
                  <div className="flex items-center gap-1.5 text-xs text-slate-400">
                    <Calendar size={12}/>
                    {new Date(ticket.createdAt).toLocaleDateString()}
                  </div>
               </div>
            </div>
