);

import React from 'react';
import { useApp } from '../AppContext';
import { TicketStatus, Ticket } from '../types';
import { AlertCircle, CheckCircle, Clock, MoreVertical, MapPin, Calendar } from 'lucide-react';

export const Tickets = () => {
  const { tickets, updateTicketStatus, properties } = useApp();

  const getAddress = (id: string) => properties.find(p => p.id === id)?.address || 'Unbekannt';

  const KanbanColumn = ({ status, title, icon }: { status: TicketStatus, title: string, icon: React.ReactNode }) => {
    const colTickets = tickets.filter(t => t.status === status);

    return (
      <div className="flex-1 min-w-[300px] bg-slate-50/80 rounded-2xl p-4 flex flex-col gap-4 h-full border border-slate-100">
        <div className="flex items-center justify-between text-slate-800 font-bold mb-2 px-1">
          <div className="flex items-center gap-2">
            <div className="p-1.5 bg-white rounded-lg shadow-sm border border-slate-100">
                {icon}
            </div>
            {title}
          </div>
          <span className="bg-white border border-slate-200 text-slate-600 px-2.5 py-0.5 rounded-full text-xs font-semibold shadow-sm">
            {colTickets.length}
          </span>
        </div>

        <div className="space-y-3 overflow-y-auto h-full pr-2 scrollbar-hide">
          {colTickets.map(ticket => (
            <div key={ticket.id} className="bg-white p-5 rounded-xl shadow-sm border border-slate-200 group hover:shadow-md transition-all duration-200 hover:-translate-y-0.5">
               <div className="flex justify-between items-start mb-3">
                 <span className={`text-[10px] font-bold px-2.5 py-1 rounded-md uppercase tracking-wider border ${
                    ticket.priority === 'HOCH' ? 'bg-red-50 text-red-700 border-red-100' :
                    ticket.priority === 'MITTEL' ? 'bg-amber-50 text-amber-700 border-amber-100' :
                    'bg-blue-50 text-blue-700 border-blue-100'
                 }`}>
                   {ticket.priority}
                 </span>
                 <div className="relative">
                    <select 
                        className="text-[10px] font-semibold bg-slate-50 border border-slate-200 rounded-lg p-1.5 outline-none cursor-pointer hover:bg-slate-100 transition-colors text-slate-600"
                        value={ticket.status}
                        onChange={(e) => updateTicketStatus(ticket.id, e.target.value as TicketStatus)}
                    >
                        <option value={TicketStatus.OPEN}>Nach Offen</option>
                        <option value={TicketStatus.IN_PROGRESS}>In Arbeit</option>
                        <option value={TicketStatus.DONE}>Erledigt</option>
                    </select>
                 </div>
               </div>

               <h4 className="font-bold text-slate-900 mb-1.5 leading-snug">{ticket.title}</h4>
               <p className="text-sm text-slate-500 mb-4 line-clamp-3 leading-relaxed">{ticket.description}</p>

               <div className="pt-3 border-t border-slate-50 flex flex-col gap-1.5">
                  <div className="flex items-center gap-1.5 text-xs font-medium text-slate-600">
                    <MapPin size={12} className="text-slate-400"/>
                    {getAddress(ticket.propertyId)}
                  </div>
                  <div className="flex items-center gap-1.5 text-xs text-slate-400">
                    <Calendar size={12}/>
                    {new Date(ticket.createdAt).toLocaleDateString('de-DE')}
                  </div>
               </div>
            </div>
          ))}
          {colTickets.length === 0 && (
            <div className="flex flex-col items-center justify-center py-12 text-slate-400 text-sm border-2 border-dashed border-slate-200 rounded-xl bg-slate-50/50">
                <p>Keine Tickets</p>
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="h-[calc(100vh-140px)] flex flex-col">
      <div className="flex justify-between items-end mb-6 flex-none">
        <div>
            <h1 className="text-3xl font-bold text-slate-900 tracking-tight">Wartung & Tickets</h1>
            <p className="text-slate-500 mt-1">Verfolgung von Reparaturen und Mieteranfragen.</p>
        </div>
        <button className="bg-slate-900 text-white px-4 py-2 rounded-lg text-sm font-medium shadow-lg shadow-slate-900/20 hover:bg-slate-800 transition-all flex items-center gap-2">
            <Plus size={16} /> Neues Ticket
        </button>
      </div>

      <div className="flex gap-6 overflow-x-auto pb-4 flex-1">
        <KanbanColumn 
            title="Gemeldet" 
            status={TicketStatus.OPEN} 
            icon={<AlertCircle size={18} className="text-red-500" />} 
        />
        <KanbanColumn 
            title="In Arbeit" 
            status={TicketStatus.IN_PROGRESS} 
            icon={<Clock size={18} className="text-amber-500" />} 
        />
        <KanbanColumn 
            title="Erledigt" 
            status={TicketStatus.DONE} 
            icon={<CheckCircle size={18} className="text-emerald-500" />} 
        />
      </div>
    </div>
  );
};

import { Plus } from 'lucide-react';

export enum TicketStatus {
  OPEN = 'OFFEN',
  IN_PROGRESS = 'IN_BEARBEITUNG',
  DONE = 'ERLEDIGT',
}

export enum TransactionType {
  INCOME = 'EINNAHME',
  EXPENSE = 'AUSGABE',
}

export interface PropertyFinancials {
  // Kaufnebenkosten %
  transferTaxPercent: number; // Grunderwerbsteuer (z.B. 3.5 - 6.5%)
  notaryPercent: number;      // Notar (ca. 1.5%)
  registryPercent: number;    // Grundbuchamt (ca. 0.5%)
  agentPercent: number;       // Makler (3.57 - 7.14%)

  // Laufende Kosten (Monatlich)
  coldRent: number;           // Kaltmiete (Wohnfläche + Stellplätze)
  operatingCostsRecoverable: number; // Umlagefähige Nebenkosten (Hausgeld Mieteranteil + Grundsteuer)
  operatingCostsNonRecoverable: number; // Nicht-umlagefähig (Verwaltung + Instandhaltungsrücklage)
  maintenanceReserve: number; // Optionale zusätzliche eigene Instandhaltungsrücklage

  // Finanzierung
  loanInterestRate: number;   // Sollzins %
  loanRepaymentRate: number;  // Tilgung % (anfänglich)
  loanAmount: number;         // Darlehenshöhe

  // Steuer
  landValuePercent: number;   // Bodenrichtwertanteil (Standard 20%, Gebäude 80%)
  personalTaxRate: number;    // Persönlicher Grenzsteuersatz (z.B. 42%)
}

export interface Property {
  id: string;
  address: string;
  city: string;
  zipCode: string;
  yearBuilt: number;
  purchasePrice: number; // Kaufpreis (Netto)
  renovationCost: number; // Anfängliche Investitionen (Küche, Sanierung)
  purchaseDate: string;  // Kaufdatum
  units: number;
  area: number; // Wohnfläche in m²
  imageUrl?: string;
  financials: PropertyFinancials;
}

