import React, { createContext, useContext, useState, useEffect, ReactNode, PropsWithChildren } from 'react';
import { Property, Ticket, Transaction, TicketStatus, Tenant, PropertyDocument } from './types';
import { SEED_PROPERTIES, SEED_TICKETS, SEED_TRANSACTIONS, SEED_TENANTS, SEED_DOCUMENTS } from './constants';

interface AppContextType {
  properties: Property[];
  tickets: Ticket[];
  transactions: Transaction[];
  tenants: Tenant[];
  documents: PropertyDocument[];
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  filteredProperties: Property[];
  addProperty: (property: Property) => void;
  updateProperty: (property: Property) => void;
  deleteProperty: (id: string) => void;
  addTransaction: (transaction: Transaction) => void;
  updateTicketStatus: (id: string, status: TicketStatus) => void;
  addTicket: (ticket: Ticket) => void;
  addTenant: (tenant: Tenant) => void;
  deleteTenant: (id: string) => void;
  addDocument: (doc: PropertyDocument) => void;
  deleteDocument: (id: string) => void;
  isLoading: boolean;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider = ({ children }: PropsWithChildren<{}>) => {
  const [properties, setProperties] = useState<Property[]>([]);
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [tenants, setTenants] = useState<Tenant[]>([]);
  const [documents, setDocuments] = useState<PropertyDocument[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Global Search State
  const [searchQuery, setSearchQuery] = useState('');

  // Load data from LocalStorage or Seed on mount
  useEffect(() => {
    const storedProps = localStorage.getItem('pm_properties');
    const storedTickets = localStorage.getItem('pm_tickets');
    const storedTx = localStorage.getItem('pm_transactions');
    const storedTenants = localStorage.getItem('pm_tenants');
    const storedDocs = localStorage.getItem('pm_documents');

    if (storedProps && storedTickets && storedTx) {
      setProperties(JSON.parse(storedProps));
      setTickets(JSON.parse(storedTickets));
      setTransactions(JSON.parse(storedTx));
      setTenants(storedTenants ? JSON.parse(storedTenants) : SEED_TENANTS);
      setDocuments(storedDocs ? JSON.parse(storedDocs) : SEED_DOCUMENTS);
    } else {
      // Seed Data
      setProperties(SEED_PROPERTIES);
      setTickets(SEED_TICKETS);
      setTransactions(SEED_TRANSACTIONS);
      setTenants(SEED_TENANTS);
      setDocuments(SEED_DOCUMENTS);

      localStorage.setItem('pm_properties', JSON.stringify(SEED_PROPERTIES));
      localStorage.setItem('pm_tickets', JSON.stringify(SEED_TICKETS));
      localStorage.setItem('pm_transactions', JSON.stringify(SEED_TRANSACTIONS));
      localStorage.setItem('pm_tenants', JSON.stringify(SEED_TENANTS));
      localStorage.setItem('pm_documents', JSON.stringify(SEED_DOCUMENTS));
    }
    setIsLoading(false);
  }, []);

  // Filter Logic
  const filteredProperties = properties.filter(p => 
    p.address.toLowerCase().includes(searchQuery.toLowerCase()) ||
    p.city.toLowerCase().includes(searchQuery.toLowerCase()) ||
    p.zipCode.includes(searchQuery)
  );

  // Persistence helpers
  const saveProperties = (data: Property[]) => {
    setProperties(data);
    localStorage.setItem('pm_properties', JSON.stringify(data));
  };

  const saveTickets = (data: Ticket[]) => {
    setTickets(data);
    localStorage.setItem('pm_tickets', JSON.stringify(data));
  };

  const saveTransactions = (data: Transaction[]) => {
    setTransactions(data);
    localStorage.setItem('pm_transactions', JSON.stringify(data));
  };

  const saveTenants = (data: Tenant[]) => {
    setTenants(data);
    localStorage.setItem('pm_tenants', JSON.stringify(data));
  };

  const saveDocuments = (data: PropertyDocument[]) => {
    setDocuments(data);
    localStorage.setItem('pm_documents', JSON.stringify(data));
  };

  // Actions
  const addProperty = (property: Property) => {
    saveProperties([...properties, property]);
  };

  const updateProperty = (updated: Property) => {
    const newProps = properties.map(p => p.id === updated.id ? updated : p);
    saveProperties(newProps);
  };

  const deleteProperty = (id: string) => {
    saveProperties(properties.filter(p => p.id !== id));
  };

  const addTransaction = (transaction: Transaction) => {
    saveTransactions([transaction, ...transactions]);
  };

  const updateTicketStatus = (id: string, status: TicketStatus) => {
    const newTickets = tickets.map(t => t.id === id ? { ...t, status } : t);
    saveTickets(newTickets);
  };

  const addTicket = (ticket: Ticket) => {
    saveTickets([ticket, ...tickets]);
  };

  const addTenant = (tenant: Tenant) => {
    saveTenants([...tenants, tenant]);
  };

  const deleteTenant = (id: string) => {
    saveTenants(tenants.filter(t => t.id !== id));
  };

  const addDocument = (doc: PropertyDocument) => {
    saveDocuments([...documents, doc]);
  };

  const deleteDocument = (id: string) => {
    saveDocuments(documents.filter(d => d.id !== id));
  };

  return (
    <AppContext.Provider value={{
      properties,
      tickets,
      transactions,
      tenants,
      documents,
      searchQuery,
      setSearchQuery,
      filteredProperties,
      addProperty,
      updateProperty,
      deleteProperty,
      addTransaction,
      updateTicketStatus,
      addTicket,
      addTenant,
      deleteTenant,
      addDocument,
      deleteDocument,
      isLoading
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within AppProvider');
  return context;
};

