import React, { useState } from 'react';
import { useApp } from '../AppContext';
import { Transaction, TransactionType } from '../types';
import { Plus, ArrowUpRight, ArrowDownLeft, X, Filter, DollarSign, PieChart as PieIcon, Wallet, Save, Download, Calendar, Tag, FileText } from 'lucide-react';
import { formatEUR } from '../utils';
