interface ConfirmDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  title: string;
  description: string;
  confirmText?: string;
  cancelText?: string;
}

export const ConfirmDialog = ({ isOpen, onClose, onConfirm, title, description, confirmText = "Löschen", cancelText = "Abbrechen" }: ConfirmDialogProps) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[60] flex items-center justify-center p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200 ring-1 ring-red-100 border border-red-50">
        <div className="p-6 text-center">
            <div className="w-12 h-12 bg-red-50 rounded-full flex items-center justify-center mx-auto mb-4 text-red-500">
                <AlertTriangle size={24} />
            </div>
            <h3 className="text-lg font-bold text-slate-900 mb-2">{title}</h3>
            <p className="text-slate-500 text-sm mb-6">{description}</p>
            <div className="flex gap-3 justify-center">
                <FancyButton variant="ghost" onClick={onClose}>{cancelText}</FancyButton>
                <FancyButton variant="danger" onClick={() => { onConfirm(); onClose(); }}>{confirmText}</FancyButton>
            </div>
        </div>
      </div>
    </div>
  );
};

export enum TicketStatus {
  OPEN = 'OFFEN',
  IN_PROGRESS = 'IN_BEARBEITUNG',
  DONE = 'ERLEDIGT',
}

export enum TransactionType {
  INCOME = 'EINNAHME',
  EXPENSE = 'AUSGABE',
}

export interface PropertyFinancials {
  // Kaufnebenkosten %
  transferTaxPercent: number; // Grunderwerbsteuer (z.B. 3.5 - 6.5%)
  notaryPercent: number;      // Notar (ca. 1.5%)
  registryPercent: number;    // Grundbuchamt (ca. 0.5%)
  agentPercent: number;       // Makler (3.57 - 7.14%)

  // Laufende Kosten (Monatlich)
  coldRent: number;           // Kaltmiete (Wohnfläche + Stellplätze)
  operatingCostsRecoverable: number; // Umlagefähige Nebenkosten (Hausgeld Mieteranteil + Grundsteuer)
  operatingCostsNonRecoverable: number; // Nicht-umlagefähig (Verwaltung + Instandhaltungsrücklage)
  maintenanceReserve: number; // Optionale zusätzliche eigene Instandhaltungsrücklage

  // Finanzierung
  loanInterestRate: number;   // Sollzins %
  loanRepaymentRate: number;  // Tilgung % (anfänglich)
  loanAmount: number;         // Darlehenshöhe

  // Steuer
  landValuePercent: number;   // Bodenrichtwertanteil (Standard 20%, Gebäude 80%)
  personalTaxRate: number;    // Persönlicher Grenzsteuersatz (z.B. 42%)
}

export interface Property {
  id: string;
  address: string;
  city: string;
  zipCode: string;
  yearBuilt: number;
  purchasePrice: number; // Kaufpreis (Netto)
  renovationCost: number; // Anfängliche Investitionen (Küche, Sanierung)
  purchaseDate: string;  // Kaufdatum
  lastRentIncreaseDate?: string; // NEU: Datum der letzten Mieterhöhung
  units: number;
  area: number; // Wohnfläche in m²
  imageUrl?: string;
  financials: PropertyFinancials;
}

export interface TicketComment {
  id: string;
  text: string;
  author: string;
  createdAt: string;
}

export interface Ticket {
  id: string;
  propertyId: string;
  title: string;
  description: string;
  status: TicketStatus;
  priority: 'NIEDRIG' | 'MITTEL' | 'HOCH';
  createdAt: string;
  comments?: TicketComment[];
}

export interface Transaction {
  id: string;
  propertyId: string;
  amount: number;
  type: TransactionType;
  category: string; 
  date: string;
  description: string;
}

export interface Tenant {
  id: string;
  propertyId: string;
  name: string;
  unit: string; // z.B. "1. OG Links"
