                <tr>
                    <td colSpan={4} className="p-8 text-center text-slate-400 italic">Keine Transaktionen für diesen Filter gefunden.</td>
                </tr>
            )}
          </tbody>
        </table>
        </div>
      </div>

       {/* Modal */}
       <Modal 
          isOpen={isModalOpen} 
          onClose={() => setIsModalOpen(false)} 
