          {/* 15% Rule Alert Section (Moved here for better layout) */}
          {warningProperties.length > 0 ? (
              <div className="bg-white border border-red-100 rounded-2xl shadow-sm overflow-hidden">
                 <div className="p-5 border-b border-red-50 flex justify-between items-center bg-red-50/30">
