// ... existing KPI_Card component remains ...
const KPI_Card = ({ title, value, icon, bg, text, trend, trendUp, subText }: any) => (
  <div className={`p-6 rounded-2xl shadow-lg shadow-slate-200/40 relative overflow-hidden group ${bg}`}>
    <div className="relative z-10">
      <div className="flex justify-between items-start mb-4">
        <div className={`p-3 rounded-xl ${bg.includes('slate-800') ? 'bg-white/10' : 'bg-slate-50'}`}>
          {icon}
        </div>
        {trend && (
