import React from 'react';
import { useApp } from '../AppContext';
import { TransactionType } from '../types';
import { calculate15PercentRule, calculateMonthlyCashflow, formatEUR } from '../utils';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { Building2, TrendingUp, DollarSign, Wallet, ArrowUpRight, ArrowDownRight, AlertTriangle, PiggyBank, Calendar, Wrench, Shield, Briefcase, CheckCircle } from 'lucide-react';

export const Dashboard = () => {
  const { properties, transactions, tenants } = useApp();

  // 1. Calculate Investment KPIs
  const totalAssetValue = properties.reduce((sum, p) => sum + p.purchasePrice, 0);
  const totalUnits = properties.reduce((sum, p) => sum + p.units, 0);

  // Calculate Global Wealth Accumulation (Tilgung)
  const totalMonthlyAmortization = properties.reduce((sum, p) => {
      return sum + calculateMonthlyCashflow(p).monthlyAmortization;
  }, 0);

  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();

  const monthlyIncome = transactions
    .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear && t.type === TransactionType.INCOME;
    })
    .reduce((sum, t) => sum + t.amount, 0);

  const monthlyExpenses = transactions
    .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear && t.type === TransactionType.EXPENSE;
    })
    .reduce((sum, t) => sum + t.amount, 0);

  const netMonthlyIncome = monthlyIncome - monthlyExpenses;

  // Pie Chart 1: Occupancy
  const occupancyData = [
    { name: 'Vermietet', value: totalUnits - 1 },
    { name: 'Leerstand', value: 1 },
  ];
  const COLORS_OCC = ['#10b981', '#cbd5e1']; 

  // Pie Chart 2: Cost Structure (Analysis of Expenses)
  // We sum up expenses by approximate categories from description or category field
  const expenseCategories = transactions
    .filter(t => t.type === TransactionType.EXPENSE)
    .reduce((acc, t) => {
        let cat = 'Sonstiges';
        const lowerCat = t.category.toLowerCase();
        if (lowerCat.includes('bank') || lowerCat.includes('zins')) cat = 'Finanzierung';
        else if (lowerCat.includes('renov') || lowerCat.includes('sanierung') || lowerCat.includes('reparatur')) cat = 'Instandhaltung';
        else if (lowerCat.includes('verwaltung') || lowerCat.includes('admin')) cat = 'Verwaltung';
        else if (lowerCat.includes('steuer') || lowerCat.includes('grundsteuer')) cat = 'Steuern & Abgaben';

        acc[cat] = (acc[cat] || 0) + t.amount;
        return acc;
    }, {} as Record<string, number>);

  const costData = Object.keys(expenseCategories).map(key => ({
      name: key,
      value: expenseCategories[key]
  }));
  const COLORS_COST = ['#3b82f6', '#f59e0b', '#ef4444', '#64748b', '#8b5cf6'];

  // Upcoming Vacancies (Lease End within 6 months)
  const today = new Date();
  const sixMonthsFromNow = new Date();
  sixMonthsFromNow.setMonth(today.getMonth() + 6);

  const expiringLeases = tenants.filter(t => {
      if (!t.leaseEnd) return false;
      const end = new Date(t.leaseEnd);
      return end >= today && end <= sixMonthsFromNow;
  }).sort((a, b) => new Date(a.leaseEnd!).getTime() - new Date(b.leaseEnd!).getTime());


  // 2. Prepare Area Chart Data (Revenue Trends)
  const chartData = [];
  for (let i = 5; i >= 0; i--) {
    const d = new Date(today.getFullYear(), today.getMonth() - i, 1);
    const monthName = d.toLocaleString('de-DE', { month: 'short' });

    const income = transactions
      .filter(t => {
        const tDate = new Date(t.date);
        return tDate.getMonth() === d.getMonth() && tDate.getFullYear() === d.getFullYear() && t.type === TransactionType.INCOME;
      })
      .reduce((sum, t) => sum + t.amount, 0);

    const expense = transactions
      .filter(t => {
        const tDate = new Date(t.date);
        return tDate.getMonth() === d.getMonth() && tDate.getFullYear() === d.getFullYear() && t.type === TransactionType.EXPENSE;
      })
      .reduce((sum, t) => sum + t.amount, 0);

    chartData.push({ name: monthName, income, expense, profit: income - expense });
  }

  // 3. 15% Rule Check
  const warningProperties = properties.map(p => {
      const check = calculate15PercentRule(p, transactions);
      return { ...p, ruleCheck: check };
  }).filter(p => p.ruleCheck.isWarning);

  return (
    <div className="space-y-8 animate-fade-in pb-8">
      <div>
        <h1 className="text-3xl font-bold text-slate-900 tracking-tight">Investment Überblick</h1>
        <p className="text-slate-500 mt-1">Echtzeit-Kennzahlen Ihres Immobilien-Portfolios.</p>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <KPI_Card 
          title="Gesamtvermögen" 
          value={`${(totalAssetValue / 1000000).toFixed(2)} Mio. €`} 
          icon={<Building2 className="text-white" size={24} />} 
          bg="bg-gradient-to-br from-slate-800 to-slate-900"
          text="text-white"
          subText={`Verteilt auf ${properties.length} Objekte`}
        />
        <KPI_Card 
          title="Monatlicher Cashflow" 
          value={formatEUR(netMonthlyIncome)} 
          icon={<Wallet className="text-emerald-600" size={24} />} 
          bg="bg-white border border-slate-100"
          text="text-slate-900"
          trend="+12.5%"
          trendUp={true}
        />
        <KPI_Card 
          title="Vermögensaufbau (Mtl.)" 
          value={`+${formatEUR(Math.round(totalMonthlyAmortization))}`} 
          icon={<PiggyBank className="text-blue-600" size={24} />} 
          bg="bg-white border border-slate-100"
          text="text-slate-900"
          subText="Durch Kredittilgung"
        />
        <KPI_Card 
          title="Vermietungsquote" 
          value={`${Math.round(((totalUnits - 1) / totalUnits) * 100)}%`} 
          icon={<TrendingUp className="text-purple-600" size={24} />} 
          bg="bg-white border border-slate-100"
          text="text-slate-900"
          trend="Stabil"
          trendUp={true}
        />
      </div>

      {/* Main Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Financial Trend */}
        <div className="lg:col-span-2 bg-white p-8 rounded-2xl border border-slate-100 shadow-lg shadow-slate-200/50">
          <div className="flex justify-between items-center mb-8">
            <div>
                <h2 className="text-xl font-bold text-slate-900">Finanzielle Entwicklung</h2>
                <p className="text-sm text-slate-500">Einnahmen vs Ausgaben (Letzte 6 Monate)</p>
            </div>
            <div className="flex items-center gap-2">
                <span className="flex items-center gap-1 text-xs font-medium text-slate-500"><div className="w-2 h-2 rounded-full bg-emerald-500"></div> Einnahmen</span>
                <span className="flex items-center gap-1 text-xs font-medium text-slate-500"><div className="w-2 h-2 rounded-full bg-slate-300"></div> Ausgaben</span>
            </div>
          </div>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorIncome" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} tickFormatter={(value) => `${value/1000}k`} />
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                  formatter={(value: number) => [`${formatEUR(value)}`, '']}
                />
                <Area type="monotone" dataKey="income" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorIncome)" />
                <Area type="monotone" dataKey="expense" stroke="#cbd5e1" strokeWidth={2} fillOpacity={0} fill="#cbd5e1" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Cost Structure Donut */}
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-lg shadow-slate-200/50 flex flex-col">
            <h2 className="text-lg font-bold text-slate-900 mb-1">Kostenstruktur</h2>
            <p className="text-xs text-slate-500 mb-6">Wofür wird Geld ausgegeben?</p>

            <div className="flex-1 min-h-[200px] relative">
                 <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie
                            data={costData}
                            innerRadius={60}
                            outerRadius={80}
                            paddingAngle={5}
                            dataKey="value"
                        >
                            {costData.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={COLORS_COST[index % COLORS_COST.length]} />
                            ))}
                        </Pie>
                        <Tooltip formatter={(value: number) => formatEUR(value)} contentStyle={{borderRadius: '8px', border: 'none', fontSize: '12px'}} />
                        <Legend verticalAlign="bottom" height={36} iconType="circle" wrapperStyle={{fontSize: '11px', paddingTop: '10px'}}/>
                    </PieChart>
                </ResponsiveContainer>
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none pb-8">
                     <Wallet className="text-slate-200" size={32} />
                </div>
            </div>
        </div>
      </div>

      {/* Bottom Row: Risks & Alerts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

          {/* Upcoming Vacancies List */}
          <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
