                            <div className="h-2 w-full bg-slate-200 rounded-full overflow-hidden">
                                <div 
                                    className={`h-full rounded-full ${p.ruleCheck.isBreached ? 'bg-red-600' : 'bg-amber-500'}`} 
                                    style={{width: `${Math.min(100, (p.ruleCheck.currentUsage / p.ruleCheck.limit) * 100)}%`}}
                                ></div>
                            </div>
                            <div className="flex justify-between text-[10px] text-slate-400 mt-1">
                                <span>Genutzt: {formatEUR(p.ruleCheck.currentUsage)}</span>
                                <span>Limit: {formatEUR(p.ruleCheck.limit)}</span>
