                                    </p>
                                    <div className="flex items-end gap-2">
                                        <span className="text-3xl font-bold text-emerald-900">+ {formatEUR(calcData.monthlyAmortization)}</span>
                                        <span className="text-emerald-600 mb-1 font-medium">/ Monat</span>
                                    </div>
                                </div>
                            </div>
